// One product per line. The Code node sandbox has no URL constructor, so the
// ASIN comes out with a regex rather than URL parsing.
const cfg = $('Set Watchlist Config').first().json;
const lines = String(cfg.product_urls || '')
  .split(/[\n,]/)
  .map((s) => s.trim())
  .filter(Boolean);

if (!lines.length) {
  throw new Error(
    'No products to watch. Paste at least one Amazon product URL into product_urls in Set Watchlist Config.'
  );
}

const seen = new Set();
const out = [];
for (const line of lines) {
  const m = line.match(/\/(?:dp|gp\/product)\/([A-Z0-9]{10})/i);
  if (!m) {
    throw new Error(
      `"${line}" is not an Amazon product URL. Expected something like https://www.amazon.com/dp/B09XS7JWHH`
    );
  }
  const asin = m[1].toUpperCase();
  if (seen.has(asin)) continue;
  seen.add(asin);
  out.push({ json: { asin, url: line.split('?')[0] } });
}

return out;

// Bright Data may hand back one item per product (n8n split the array) or a
// single item holding the whole array. Read every input item, or we keep only
// the first product and silently drop the rest.
const rows = [];
const errors = [];

for (const item of $input.all()) {
  let payload = item.json.body ?? item.json;
  if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch { continue; }
  }
  if (payload && payload.snapshot_id && !Array.isArray(payload)) {
    throw new Error(
      `Bright Data returned snapshot_id ${payload.snapshot_id} instead of rows. ` +
      'The sync scrape endpoint gives up after about a minute - lower max_products, ' +
      'or switch to the async trigger endpoint.'
    );
  }
  // Bright Data answers validation errors with HTTP 200, so a bad request looks
  // like a successful call. Surface the real message instead of an empty result.
  if (payload && payload.error) {
    const detail = Array.isArray(payload.details)
      ? payload.details.map((d) => d.message).join('; ')
      : '';
    errors.push(payload.error + (detail ? ': ' + detail : ''));
    continue;
  }
  if (Array.isArray(payload)) rows.push(...payload);
  else if (payload) rows.push(payload);
}

if (!rows.length) {
  throw new Error(
    errors.length
      ? `Bright Data rejected the scrape: ${errors[0]}`
      : 'Bright Data returned no product rows. Check that the URLs are live Amazon product pages.'
  );
}

const checkedAt = new Date().toISOString();
const out = [];
for (const r of rows) {
  if (!r || !r.asin) continue;
  const price = Number(r.final_price ?? r.initial_price ?? 0) || null;
  out.push({
    json: {
      checked_at: checkedAt,
      asin: r.asin,
      title: String(r.title || '').slice(0, 180),
      brand: r.brand || '',
      price,
      list_price: Number(r.initial_price ?? 0) || null,
      currency: r.currency || '',
      in_stock: r.is_available === true || /in stock/i.test(String(r.availability || '')),
      availability: r.availability || '',
      rating: Number(r.rating ?? 0) || null,
      reviews_count: Number(r.reviews_count ?? 0) || null,
      buybox_seller: r.buybox_seller || r.seller_name || '',
      sellers: Number(r.number_of_sellers ?? 0) || null,
      coupon: r.coupon || '',
      bestseller_rank: Number(r.root_bs_rank ?? 0) || null,
      url: (r.input && r.input.url) || r.url || '',
    },
  });
}

if (!out.length) {
  throw new Error('Bright Data returned rows but none carried an ASIN.');
}
return out;

// The history sheet holds one row per product per run. Today's rows are appended
// on the other branch, after this node, so everything read here is older.
const cfg = $('Set Watchlist Config').first().json;
const dropPct = Number(cfg.alert_drop_pct ?? 5);
const risePct = Number(cfg.alert_rise_pct ?? 5);
const today = $('Flatten Product Snapshots').all().map((i) => i.json);

const history = [];
for (const item of $input.all()) {
  const r = item.json || {};
  // Blank rows, header rows and a sheet that does not exist yet all land here.
  if (!r.asin || !r.checked_at) continue;
  history.push(r);
}

const baseline = {};
for (const r of history) {
  const prev = baseline[r.asin];
  if (!prev || String(r.checked_at) > String(prev.checked_at)) baseline[r.asin] = r;
}

const truthy = (v) => v === true || String(v).toLowerCase() === 'true';
const changes = [];

for (const cur of today) {
  const prev = baseline[cur.asin];
  if (!prev) continue; // first run for this product - nothing to compare against
  const prevPrice = Number(prev.price) || null;
  const events = [];
  let pct = null;

  if (prevPrice && cur.price) {
    pct = ((cur.price - prevPrice) / prevPrice) * 100;
    if (pct <= -dropPct) {
      events.push(`price dropped ${Math.abs(pct).toFixed(1)}% (${prevPrice} to ${cur.price} ${cur.currency})`);
    } else if (pct >= risePct) {
      events.push(`price rose ${pct.toFixed(1)}% (${prevPrice} to ${cur.price} ${cur.currency})`);
    }
  }

  const wasInStock = truthy(prev.in_stock);
  if (wasInStock && !cur.in_stock) events.push('went out of stock');
  if (!wasInStock && cur.in_stock) events.push('came back in stock');

  if (prev.buybox_seller && cur.buybox_seller && prev.buybox_seller !== cur.buybox_seller) {
    events.push(`buy box moved from ${prev.buybox_seller} to ${cur.buybox_seller}`);
  }

  if (!events.length) continue;
  changes.push({
    ...cur,
    previous_price: prevPrice,
    previous_seller: prev.buybox_seller || '',
    previous_checked_at: prev.checked_at,
    change_pct: pct === null ? null : Number(pct.toFixed(1)),
    events: events.join('; '),
  });
}

return [{
  json: {
    has_changes: changes.length > 0,
    products_checked: today.length,
    baseline_rows: history.length,
    changes,
    snapshot: today,
  },
}];

// Runs once per changed product. Google Shopping rows carry base64 logos and
// images that would blow up the prompt, and Google repeats the product title
// twice inside one string - strip both here, not downstream.
const changed = $('Split Out Changed Products').item.json;

let payload = $json.body ?? $json;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch { payload = {}; }
}
if (payload && payload.error) {
  const detail = Array.isArray(payload.details)
    ? payload.details.map((d) => d.message).join('; ')
    : '';
  return { json: { ...changed, cheaper_offers: [], offers_error: payload.error + (detail ? ': ' + detail : '') } };
}

const undouble = (s) => {
  const t = String(s || '').trim();
  const half = t.length / 2;
  return t.length % 2 === 0 && t.slice(0, half) === t.slice(half) ? t.slice(0, half) : t;
};
const toNumber = (s) => {
  const m = String(s || '').replace(/,/g, '').match(/[\d.]+/);
  return m ? Number(m[0]) : null;
};

const USED = /pre-?owned|used|refurb|open box|renewed/i;

const offers = [];
for (const r of Array.isArray(payload.shopping) ? payload.shopping : []) {
  const price = toNumber(r.price);
  if (!price) continue;
  offers.push({
    shop: r.shop || '',
    price,
    used: USED.test(String(r.tag || '')),
    title: undouble(r.title).slice(0, 120),
  });
}
offers.sort((a, b) => a.price - b.price);

// Google Shopping matches on the product name, so a query for a $250 headphone
// also returns cases, cables and outright mismatches for $20. Anything under
// 40% of the Amazon price is treated as a different product, not a bargain.
const mine = Number(changed.price) || null;
const floor = mine ? mine * 0.4 : 0;
const plausible = offers.filter((o) => o.price >= floor);
const newOffers = plausible.filter((o) => !o.used);
const usedOffers = plausible.filter((o) => o.used);

return {
  json: {
    ...changed,
    offers_seen: offers.length,
    offers_ignored_as_mismatch: offers.length - plausible.length,
    market_low_new: newOffers.length ? newOffers[0].price : null,
    market_low_used: usedOffers.length ? usedOffers[0].price : null,
    cheaper_offers: (mine ? newOffers.filter((o) => o.price < mine) : newOffers)
      .slice(0, 5)
      .map((o) => ({ shop: o.shop, price: o.price, title: o.title })),
  },
};
